import React from 'react';
import { useLocation } from 'react-router-dom';
import './Profile.css'; // Import the CSS file

const Profile = () => {
  const location = useLocation();
  const { item, role } = location.state || {}; // Access the passed item and role

  console.log('Profile data:', item, role); // For debugging - remove later

  return (
    <div className="profile-container"> {/* Use CSS class instead of inline style */}
      <h1 className="profile-title">Hello</h1> {/* Use CSS class instead of inline style */}
      {/* You can add more content here later, e.g., display item details */}
    </div>
  );
};

export default Profile;
